import 'package:flutter/material.dart';
import '../app.dart';
import '../state/app_state.dart';
class LoginScreen extends StatefulWidget { const LoginScreen({super.key}); @override State<LoginScreen> createState()=>_LoginScreenState(); }
class _LoginScreenState extends State<LoginScreen>{ final email=TextEditingController(text:'member@fitforge.ai'); final password=TextEditingController(text:'Fitforge@12345'); String message=''; @override Widget build(BuildContext context){ final state=AppScope.of(context); return Scaffold(body: SafeArea(child: Padding(padding: const EdgeInsets.all(24), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children:[ const Spacer(), Text('FITFORGE AI', style: Theme.of(context).textTheme.displaySmall?.copyWith(fontWeight: FontWeight.bold)), const SizedBox(height:12), SegmentedButton<AppRole>(segments: const [ButtonSegment(value: AppRole.member,label:Text('Member')), ButtonSegment(value: AppRole.trainer,label:Text('Trainer'))], selected:{state.role}, onSelectionChanged:(v)=>state.setRole(v.first)), const SizedBox(height:16), TextField(controller: email, decoration: const InputDecoration(labelText:'Email')), TextField(controller: password, decoration: const InputDecoration(labelText:'Password'), obscureText:true), const SizedBox(height:16), FilledButton(onPressed:() async { try { await state.login(email.text,password.text); } catch (_) { message='Demo mode: backend not reachable'; } if(context.mounted) Navigator.pushReplacementNamed(context,'/home'); }, child: const Text('Login')), Text(message), const Spacer()] )))); }}
